    int primitives, bones;
    SubMesh(int p, int b) : primitives(p), bones(b) { }
    SubMesh(const SubMesh& o) : primitives(o.primitives), bones(o.bones) { ++g_copies; }
    ~SubMesh() { ++g_dtors; }
};

